<main class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="<?= base_url('admin') ?>"><span class="brand-mark">S</span><span>EUPHORIA <strong>OPS</strong></span></a><div class="admin-nav"><span class="eyebrow">COMMAND</span><a href="<?= base_url('admin') ?>">Overview</a><a class="admin-nav-active" href="<?= base_url('admin/events') ?>">Events</a><a href="<?= base_url('admin/registrations') ?>">Registrations</a><a href="<?= base_url('admin/attendance') ?>">Attendance</a><span class="eyebrow nav-spacer">SYSTEM</span><a href="<?= base_url('admin/settings') ?>">Settings</a></div><a href="<?= base_url('logout') ?>" class="admin-logout">Sign out</a></aside><section class="admin-content"><div class="admin-topbar"><div><span class="eyebrow accent">PROGRAMME BUILDER</span><h1>Events</h1></div><a class="button button-yellow" href="<?= base_url('admin/events/new') ?>" data-testid="events-new-button">New event <span>↗</span></a></div><div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">PUBLISHED LINEUP</span><h2><?= count($events) ?> events</h2></div><span class="mono">SORT / RECENT</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Event</th><th>Type</th><th>Fee</th><th>Status</th><th>Capacity</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr data-testid="admin-event-row"><td><strong><?= esc($event['name']) ?></strong><span class="table-sub">/<?= esc($event['slug']) ?></span></td><td><?= esc(ucfirst($event['event_type'])) ?></td><td><?= $event['fee'] > 0 ? esc(money($event['fee'])) : 'FREE' ?></td><td><span class="<?= status_class($event['status']) ?>"><?= esc(strtoupper(str_replace('_',' ',$event['status']))) ?></span></td><td><?= esc($event['capacity'] ?: '∞') ?></td></tr><?php endforeach ?></tbody></table></div></div></section></main>